#!/usr/bin/env python3
"""Validation script for pipeline outputs."""
import csv
import json
import os


def validate_clean_stops():
    """Validate cleaned GTFS stops output."""
    filepath = "outputs/t05_clean_stops.csv"
    entries = []
    if not os.path.exists(filepath):
        entries.append({
            "check_name": "clean_gtfs_stops",
            "passed": False,
            "message": f"File not found: {filepath}"
        })
        return entries

    with open(filepath, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Check required columns
    required_cols = ["stop_id", "stop_name", "stop_lat", "stop_lon"]
    if not all(col in rows[0] for col in required_cols):
        entries.append({
            "check_name": "clean_gtfs_stops",
            "passed": False,
            "message": "Missing required columns in clean GTFS stops"
        })
        return entries

    # Check all rows have lat/lon
    missing_coords = 0
    for row in rows:
        try:
            float(row["stop_lat"])
            float(row["stop_lon"])
        except (ValueError, TypeError):
            missing_coords += 1

    if missing_coords > 0:
        entries.append({
            "check_name": "clean_gtfs_stops",
            "passed": False,
            "message": f"{missing_coords} rows missing valid lat/lon coordinates"
        })
    else:
        entries.append({
            "check_name": "clean_gtfs_stops",
            "passed": True,
            "message": f"Validated {len(rows)} cleaned GTFS stops with valid coordinates"
        })
    return entries


def validate_pois():
    """Validate cleaned POIs output."""
    filepath = "outputs/t08_pois_clean.csv"
    entries = []
    if not os.path.exists(filepath):
        entries.append({
            "check_name": "clean_pois",
            "passed": False,
            "message": f"File not found: {filepath}"
        })
        return entries

    with open(filepath, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Check required columns
    required_cols = ["qid", "label", "poi_type", "latitude", "longitude", "source"]
    if not all(col in rows[0] for col in required_cols):
        entries.append({
            "check_name": "clean_pois",
            "passed": False,
            "message": "Missing required columns in cleaned POIs"
        })
        return entries

    # Check all rows have valid lat/lon
    missing_coords = 0
    for row in rows:
        try:
            float(row["latitude"])
            float(row["longitude"])
        except (ValueError, TypeError):
            missing_coords += 1

    if missing_coords > 0:
        entries.append({
            "check_name": "clean_pois",
            "passed": False,
            "message": f"{missing_coords} rows missing valid lat/lon coordinates"
        })
    else:
        entries.append({
            "check_name": "clean_pois",
            "passed": True,
            "message": f"Validated {len(rows)} cleaned POIs with valid coordinates"
        })
    return entries


def validate_accessibility_scores():
    """Validate accessibility scores output."""
    filepath = "outputs/t10_accessibility_scores.csv"
    entries = []
    if not os.path.exists(filepath):
        entries.append({
            "check_name": "accessibility_scores",
            "passed": False,
            "message": f"File not found: {filepath}"
        })
        return entries

    with open(filepath, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Check required columns
    required_cols = ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]
    if not all(col in rows[0] for col in required_cols):
        entries.append({
            "check_name": "accessibility_scores",
            "passed": False,
            "message": "Missing required columns in accessibility scores"
        })
        return entries

    # Check all rows have valid numeric values
    missing_values = 0
    for row in rows:
        try:
            float(row["distance_m"])
            float(row["n_departures"])
            float(row["n_routes"])
            float(row["accessibility_score"])
        except (ValueError, TypeError):
            missing_values += 1

    if missing_values > 0:
        entries.append({
            "check_name": "accessibility_scores",
            "passed": False,
            "message": f"{missing_values} rows missing valid numeric values"
        })
    else:
        entries.append({
            "check_name": "accessibility_scores",
            "passed": True,
            "message": f"Validated {len(rows)} accessibility scores with valid metrics"
        })
    return entries


def validate_city_clusters():
    """Validate city clusters output."""
    filepath = "outputs/t13_city_clusters.csv"
    entries = []
    if not os.path.exists(filepath):
        entries.append({
            "check_name": "city_clusters",
            "passed": False,
            "message": f"File not found: {filepath}"
        })
        return entries

    with open(filepath, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Check required columns
    required_cols = ["city_id", "city_name", "year", "cluster_id"]
    if not all(col in rows[0] for col in required_cols):
        entries.append({
            "check_name": "city_clusters",
            "passed": False,
            "message": "Missing required columns in city clusters"
        })
        return entries

    # Check year values are valid
    invalid_years = 0
    for row in rows:
        try:
            year = int(row["year"])
            if year < 2020 or year > 2030:
                invalid_years += 1
        except (ValueError, TypeError):
            invalid_years += 1

    if invalid_years > 0:
        entries.append({
            "check_name": "city_clusters",
            "passed": False,
            "message": f"{invalid_years} rows with invalid year values"
        })
    else:
        entries.append({
            "check_name": "city_clusters",
            "passed": True,
            "message": f"Validated {len(rows)} city cluster entries with valid years"
        })
    return entries


def main():
    """Run all validations and write summary."""
    all_entries = []

    all_entries.extend(validate_clean_stops())
    all_entries.extend(validate_pois())
    all_entries.extend(validate_accessibility_scores())
    all_entries.extend(validate_city_clusters())

    # Ensure outputs directory exists
    os.makedirs("outputs", exist_ok=True)

    # Write summary
    summary_path = "outputs/t14_validation_summary.json"
    with open(summary_path, "w", encoding="utf-8") as f:
        json.dump(all_entries, f, indent=2)

    print(f"Validation complete. Summary written to {summary_path}")
    print(f"Total checks: {len(all_entries)}")
    print(f"Passed: {sum(1 for e in all_entries if e["passed"])}")
    print(f"Failed: {sum(1 for e in all_entries if not e["passed"])}")


if __name__ == "__main__":
    main()

